function executeSkill(context) {
  var caster = context.piece; var target = selectTarget({ type: 'piece', range: 99, filter: 'ally' });
  if (!target || target.needsTargetSelection) return target;
  if (target.currentHp <= 0 || target.ownerPlayerId !== caster.ownerPlayerId) return { success: false, message: '命运庇护只能选择存活友方' };
  var existing = target.statusTags && target.statusTags.find(function(tag) { return tag.type === 'velen-fate-shelter'; });
  if (existing) return { success: false, message: '目标已经获得命运庇护' };
  addStatusEffectById(target.instanceId, { id: 'velen-fate-shelter-' + caster.instanceId + '-' + target.instanceId, name: '命运庇护', type: 'velen-fate-shelter', currentDuration: -1, currentUses: -1, intensity: 8, stacks: 1, sourceId: caster.instanceId, createdTurnNumber: battle.turn.turnNumber, relatedRules: ['rule-velen-fate-target'] });
  addRuleById(target.instanceId, 'rule-velen-fate-target');
  return { success: true, message: caster.name + '为' + target.name + '预见了命运庇护' };
}
